import Foundation
import Vision
import AppKit

let path = CommandLine.arguments[1]
guard let img = NSImage(contentsOfFile: path),
      let tiff = img.tiffRepresentation,
      let rep = NSBitmapImageRep(data: tiff),
      let cg = rep.cgImage else {
    fputs("load fail\n", stderr); exit(1)
}
let req = VNRecognizeTextRequest()
req.recognitionLanguages = ["zh-Hans", "en-US"]
req.recognitionLevel = .accurate
req.usesLanguageCorrection = false
let handler = VNImageRequestHandler(cgImage: cg, options: [:])
try handler.perform([req])
guard let obs = req.results else { exit(0) }
let w = CGFloat(cg.width), h = CGFloat(cg.height)
for o in obs {
    guard let top = o.topCandidates(1).first else { continue }
    let t = top.string
    if t.contains("2026") || t.contains("3") && t.contains("20") || t.contains("月") || t.contains("年") {
        let r = o.boundingBox // normalized, origin bottom-left
        let x = r.minX * w
        let y = (1 - r.maxY) * h
        let bw = r.width * w
        let bh = r.height * h
        print("TEXT=\(t)|CONF=\(top.confidence)|BOX=\(Int(x)),\(Int(y)),\(Int(bw)),\(Int(bh))")
    }
}
