    if br < 120 and dbg(r, g, b) > 45:
        continue
    subj[y][x] = 0
    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
        if 0 <= nx < w and 0 <= ny < h and not vis[ny][nx]:
            nr, ng, nb = px[nx, ny]
            nbr = (nr + ng + nb) / 3
            if (nbr > 168 and sat(nr, ng, nb) < 0.18 and dbg(nr, ng, nb) < 80) or subj[ny][nx] == 0:
                vis[ny][nx] = True
                q.append((nx, ny))

def to_img(s):
    m = Image.new("L", (w, h))
    p = m.load()
    for y in range(h):
        for x in range(w):
            p[x, y] = 255 if s[y][x] else 0
    return m

def from_img(m):
    p = m.load()
    return [[1 if p[x, y] > 128 else 0 for x in range(w)] for y in range(h)]

subj = from_img(to_img(subj).filter(ImageFilter.MaxFilter(3)).filter(ImageFilter.MinFilter(3)))

def border4(x, y, s):
    if not s[y][x]:
        return False
    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        xx, yy = x + dx, y + dy
        if not (0 <= xx < w and 0 <= yy < h) or s[yy][xx] == 0:
            return True
    return False

# Peel light fringe mainly in hair band
for it in range(3):
    clr = []
    for y in range(HAIR_Y):
        for x in range(w):
            if subj[y][x] and border4(x, y, subj):
                r, g, b = px[x, y]
                br = (r + g + b) / 3
                if br > 105 or (dbg(r, g, b) < 55 and br > 90):
                    clr.append((x, y))
    for x, y in clr:
        subj[y][x] = 0

# Mild body/shoulder light fringe
clr = []
for y in range(HAIR_Y, h):
    for x in range(w):
        if subj[y][x] and border4(x, y, subj):
            r, g, b = px[x, y]
            if (r + g + b) / 3 > 170 and sat(r, g, b) < 0.12:
                clr.append((x, y))
for x, y in clr:
    subj[y][x] = 0

# Hair color samples for edge fix only
hair_cols = []
for y in range(int(h * 0.06), int(h * 0.28)):
    for x in range(int(w * 0.30), int(w * 0.70)):
        if subj[y][x]:
            r, g, b = px[x, y]
            if (r + g + b) / 3 < 75:
                hair_cols.append((r, g, b))
avg_hair = tuple(sum(c[i] for c in hair_cols) // len(hair_cols) for i in range(3)) if hair_cols else (20, 18, 18)

near_dark = {}
for y in range(HAIR_Y + 8):
    for x in range(w):
        if not subj[y][x] or not border4(x, y, subj):
            continue
        dark = None
        for rad in range(1, 10):
            for dy in range(-rad, rad + 1):
                for dx in range(-rad, rad + 1):
                    xx, yy = x + dx, y + dy
                    if 0 <= xx < w and 0 <= yy < h and subj[yy][xx] and not border4(xx, yy, subj):
                        rr, gg, bb = px[xx, yy]
                        if (rr + gg + bb) / 3 < 90:
                            dark = (rr, gg, bb)
                            break
                if dark:
                    break
            if dark:
                break
        near_dark[(x, y)] = dark or avg_hair

out = Image.new("RGB", (w, h), RED)
op = out.load()

# Paste original pixels — preserve face exactly
for y in range(h):
    for x in range(w):
        if not subj[y][x]:
            continue
        r, g, b = px[x, y]
        # only replace light hair-border fringe
        if y < HAIR_Y and border4(x, y, subj) and (r + g + b) / 3 > 95:
            op[x, y] = near_dark.get((x, y), avg_hair)
        else:
            op[x, y] = (r, g, b)

# Soft AA outside hair edge
for y in range(1, HAIR_Y + 5):
    for x in range(1, w - 1):
        if subj[y][x]:
            continue
        adj = False
        hc = None
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            if subj[y + dy][x + dx]:
                adj = True
                hc = op[x + dx, y + dy]
                break
        if adj and hc is not None:
            t = 0.16
            op[x, y] = tuple(int(RED[i] * (1 - t) + hc[i] * t) for i in range(3))

# Kill pink/gray halo in hair band
for y in range(HAIR_Y + 5):
    for x in range(w):
        r, g, b = op[x, y]
        if r > 240 and g < 40 and b < 40:
            continue
        br = (r + g + b) / 3
        if r > 150 and g > 55 and b > 55 and 90 < br < 210:
            nred = nh = 0
            dark = None
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    xx, yy = x + dx, y + dy
                    if not (0 <= xx < w and 0 <= yy < h):
                        continue
                    rr, gg, bb = op[xx, yy]
                    if rr > 240 and gg < 40 and bb < 40:
                        nred += 1
                    if (rr + gg + bb) / 3 < 70:
                        nh += 1
                        dark = (rr, gg, bb)
            if nh and nred:
                op[x, y] = dark or avg_hair
            elif nred >= 4 and br > 120:
                op[x, y] = RED

out.save(out_desk, quality=96)
out.resize((min(420, w), int(min(420, w) * h / w)), Image.Resampling.LANCZOS).save(qa, quality=93)
out.crop((100, 120, 430, 520)).resize((280, 340), Image.Resampling.LANCZOS).save(
    Path("/Users/mac/Desktop/CHcode/tmp/contract_edit/id_red_fix_face.jpg"), quality=93
)
print("size", w, h, "saved", out_desk)
